INSERT INTO diet_catalog (
    diet_key, display_label, category, emoji, short_desc,
    evidence_grade, restrictiveness, is_timing_pattern, is_default,
    ai_rules, allowed_groups, restricted_groups, classifier_terms, macro_targets,
    easy_matches, adaptable_matches, hard_conflicts, is_condition
  ) VALUES (
    'gluten-free', 'Gluten-Free', 'condition', '🌾', 'Strict gluten-free for coeliac disease and gluten sensitivity — no wheat, barley or rye',
    'A', 4, 0, 0,
    'GLUTEN-FREE DIET RULES — COELIAC-SAFE STANDARD. Follow strictly:

1. NO GLUTEN, EVER. This is a medical diet, not a preference. Even small amounts can harm someone with coeliac disease.
2. FORBIDDEN GRAINS AND DERIVATIVES:
   - Wheat in every form: flour, whole wheat, wholemeal, durum, semolina, spelt, kamut, farro, emmer, einkorn, bulgur, couscous, orzo, graham, wheat starch, wheat germ, wheat bran.
   - Barley, rye, triticale.
   - Malt, malt extract, malt syrup, malt vinegar, brewer''s yeast.
3. FORBIDDEN INGREDIENTS AND PRODUCTS:
   - Regular soy sauce, teriyaki, hoisin, oyster sauce (unless explicitly gluten-free).
   - Regular bread, pasta, noodles, couscous, breadcrumbs, panko, batter, pastry, pizza, crackers, pretzels.
   - Beer, ale, lager (unless labelled gluten-free).
   - Seitan and any wheat protein.
   - Sausages, meatballs, deli meats, pate and processed meats containing rusk or fillers.
   - Bouillon cubes, stock powder, gravy granules and soup bases (unless gluten-free).
   - Battered or breaded foods, including shared fryer items.
4. SAFE STAPLES TO BUILD MEALS AROUND:
   - Rice, corn, quinoa, buckwheat, millet, sorghum, teff, amaranth, potatoes, sweet potatoes.
   - Fresh vegetables and fruit, legumes, plain tofu, eggs, fresh meat, poultry, fish, seafood.
   - Plain dairy, olive oil, nuts, seeds, herbs, spices, citrus, vinegar except malt vinegar.
   - Certified gluten-free oats only. Never regular oats.
   - Use tamari or gluten-free soy sauce instead of regular soy sauce.
   - Thicken with cornstarch, arrowroot, rice flour or chickpea flour — never wheat flour.
5. CROSS-CONTACT: Do not suggest recipes that rely on shared toasters, fryers, colanders, pasta water or flour dusting. Do not suggest "just remove the bread" — crumbs and sauces contaminate the dish.
6. LABEL AWARENESS: "Wheat-free" is not gluten-free. Avoid any ingredient that may contain wheat, barley, rye or malt.
7. NUTRITION: Build meals from naturally gluten-free whole foods, not refined GF substitutes. Include fibre-rich vegetables, legumes and whole GF grains; include iron-rich foods with vitamin C; include calcium sources.
8. This app provides general dietary guidance, not medical advice. The user should follow their clinician''s and dietitian''s instructions.', '["vegetables","leafy-greens","fruit","legumes","potatoes","rice","corn","quinoa","buckwheat","millet","sorghum","teff","amaranth","certified-gf-oats","meat","poultry","fish","seafood","eggs","plain-dairy","nuts","seeds","olive-oil","herbs-spices","gluten-free-flours","tamari","gluten-free-pasta","gluten-free-bread","vinegar-not-malt"]', '["wheat","barley","rye","triticale","gluten-containing-grains","wheat-flour","malt","seitan","regular-soy-sauce","regular-pasta","regular-bread","breadcrumbs","couscous","bulgur","semolina","durum","spelt","kamut","farro","beer","wheat-based-bouillon","processed-meat-with-fillers","battered-fried-foods","wheat-based-snacks"]', '{"wheat":"wheat","whole wheat":"wheat","wholemeal":"wheat","wheat flour":"wheat-flour","all purpose flour":"wheat-flour","white flour":"wheat-flour","bread flour":"wheat-flour","cake flour":"wheat-flour","self raising flour":"wheat-flour","wheat germ":"wheat","wheat bran":"wheat","vital wheat gluten":"wheat","durum":"durum","semolina":"semolina","spelt":"spelt","kamut":"kamut","farro":"farro","emmer":"wheat","einkorn":"wheat","bulgur":"bulgur","couscous":"couscous","orzo":"regular-pasta","barley":"barley","rye":"rye","rye bread":"rye","triticale":"triticale","malt":"malt","malt extract":"malt","malt syrup":"malt","malt vinegar":"malt","brewers yeast":"malt","beer":"beer","ale":"beer","lager":"beer","bread":"regular-bread","baguette":"regular-bread","bagel":"regular-bread","croissant":"regular-bread","pita":"regular-bread","naan":"regular-bread","flour tortilla":"regular-bread","breadcrumbs":"breadcrumbs","bread crumbs":"breadcrumbs","panko":"breadcrumbs","pasta":"regular-pasta","spaghetti":"regular-pasta","macaroni":"regular-pasta","lasagna":"regular-pasta","noodles":"regular-pasta","ramen":"regular-pasta","udon":"regular-pasta","egg noodles":"regular-pasta","wonton wrapper":"regular-pasta","dumpling wrapper":"regular-pasta","batter":"battered-fried-foods","tempura":"battered-fried-foods","breaded":"battered-fried-foods","soy sauce":"regular-soy-sauce","teriyaki":"regular-soy-sauce","hoisin":"regular-soy-sauce","oyster sauce":"regular-soy-sauce","seitan":"seitan","bouillon":"wheat-based-bouillon","stock cube":"wheat-based-bouillon","gravy":"wheat-based-bouillon","sausage":"processed-meat-with-fillers","meatball":"processed-meat-with-fillers","deli meat":"processed-meat-with-fillers","imitation crab":"processed-meat-with-fillers","surimi":"processed-meat-with-fillers","cracker":"wheat-based-snacks","pretzel":"wheat-based-snacks","biscuit":"wheat-based-snacks","cookie":"wheat-based-snacks","cake":"wheat-based-snacks","pastry":"wheat-based-snacks","pie crust":"wheat-based-snacks","pizza":"wheat-based-snacks","rice":"rice","corn":"corn","quinoa":"quinoa","buckwheat":"buckwheat","millet":"millet","sorghum":"sorghum","teff":"teff","amaranth":"amaranth","certified gluten free oats":"certified-gf-oats","gluten free oats":"certified-gf-oats","tamari":"tamari","gluten free soy sauce":"tamari","rice flour":"gluten-free-flours","almond flour":"gluten-free-flours","chickpea flour":"gluten-free-flours","cornmeal":"gluten-free-flours","cornstarch":"gluten-free-flours","potato":"potatoes","sweet potato":"potatoes","lentils":"legumes","chickpeas":"legumes","black beans":"legumes"}', '{"gluten_ppm_max":0,"fiber_g_day_min":25,"protein_g_meal_min":20}',
    '["mediterranean","dash","mind","plant-based","vegan","vegetarian","pescatarian","flexitarian","volumetrics","high-protein","low-sodium","diabetes-friendly","bone-health"]', '{"keto":"Rice/potatoes can be swapped for extra vegetables; keep the shared protein and fat sources gluten-free","paleo":"Almost fully compatible — paleo already excludes grains; confirm no wheat-based condiments","low-fodmap":"Use GF grains and low-FODMAP vegetables; watch garlic/onion content","intermittent-fasting":"Timing pattern is orthogonal — follow the GF rules inside the eating window","whole30":"Whole30 is naturally GF if no wheat-based additives are used","macrobiotic":"Use rice, millet and buckwheat; avoid wheat-based soy sauce","hclf-811":"Fruit and vegetables are naturally GF; ensure no wheat-based supplements","mcdougall":"Rice and potatoes are GF; avoid wheat-based bread and pasta"}', '{"carnivore":"No shared carbohydrate base, but all meat/fish is GF — meals can still be shared"}', 1
  );
INSERT INTO diet_catalog (
    diet_key, display_label, category, emoji, short_desc,
    evidence_grade, restrictiveness, is_timing_pattern, is_default,
    ai_rules, allowed_groups, restricted_groups, classifier_terms, macro_targets,
    easy_matches, adaptable_matches, hard_conflicts, is_condition
  ) VALUES (
    'low-sodium', 'Low-Sodium / Heart', 'condition', '❤️', 'Cardiac-friendly eating — sodium ≤1,500-2,300mg, low saturated fat, high fibre',
    'A', 3, 0, 0,
    'LOW-SODIUM / CARDIAC-FRIENDLY DIET RULES — Follow strictly:

1. SODIUM IS THE PRIMARY TARGET:
   - Design meals to approximately 500mg sodium or less per serving.
   - Do NOT add salt in cooking or at the table.
   - Do NOT use salt-based seasonings, salted butter, or salt blends.
   - Season with herbs, spices, citrus juice, vinegar, garlic, onion, ginger and chilli instead.
2. FORBIDDEN HIGH-SODIUM INGREDIENTS:
   - Soy sauce, tamari, fish sauce, oyster sauce, teriyaki, hoisin, miso.
   - Bouillon cubes, stock cubes, gravy granules, regular broth.
   - Pickles, olives, capers, sauerkraut, kimchi.
   - Bacon, ham, sausage, salami, pepperoni, deli meat, hot dogs, chorizo, prosciutto.
   - Canned soup, instant noodles, frozen ready meals, salted canned vegetables.
   - Crisps, pretzels, salted crackers, salted popcorn, salted nuts.
   - Parmesan, feta, halloumi, blue cheese, processed cheese.
   - Salt substitutes that contain sodium.
3. FAT QUALITY:
   - Keep saturated fat low: limit butter, cream, fatty meat, coconut oil and full-fat dairy.
   - Avoid trans fat and partially hydrogenated oils; no commercial pastries or deep-fried food.
   - Use olive oil, avocado, unsalted nuts and seeds as the main fats.
4. EMPHASISE:
   - Vegetables and fruit at every meal (aim for half the plate).
   - Whole grains, oats, barley, brown rice, quinoa.
   - Legumes, lentils, chickpeas and beans (no-salt-added or rinsed).
   - Oily fish such as salmon, sardines and mackerel at least twice a week.
   - Skinless poultry, tofu and eggs; limit red meat to once a week.
   - Unsalted nuts and seeds.
5. FIBRE: aim for 25-30g per day from whole grains, legumes, vegetables and fruit.
6. POTASSIUM: include potassium-rich foods such as leafy greens, beans, potatoes, bananas and tomatoes. Do NOT apply this if the user has kidney disease — that requires medical guidance.
7. NO ADDED SUGAR OR SUGARY DRINKS: avoid soft drinks, sweetened juices and energy drinks.
8. COOKING METHOD: grill, bake, steam, poach or saute with olive oil. Do not deep-fry.
9. If canned ingredients are used, specify no-salt-added and rinsed.
10. This app provides general dietary guidance, not medical advice. Heart failure, kidney disease and medication changes require a clinician.', '["vegetables","leafy-greens","fruit","whole-grains","oats","barley","brown-rice","quinoa","legumes","no-salt-added-canned-goods","fresh-fish","oily-fish","poultry","lean-meat","eggs","tofu","plain-low-fat-dairy","unsalted-nuts","unsalted-seeds","olive-oil","avocado","herbs-spices","citrus","vinegar","garlic","onion","potatoes","sweet-potatoes"]', '["salt","high-sodium-condiments","soy-sauce","bouillon-broth","pickled-foods","cured-meat","processed-meat","salty-snacks","canned-high-sodium","high-sodium-cheese","trans-fat","saturated-fat-heavy","fried-food","sugary-drinks","alcohol"]', '{"salt":"salt","sea salt":"salt","kosher salt":"salt","table salt":"salt","salted butter":"salt","garlic salt":"salt","onion salt":"salt","celery salt":"salt","seasoning salt":"salt","soy sauce":"soy-sauce","tamari":"soy-sauce","fish sauce":"high-sodium-condiments","oyster sauce":"high-sodium-condiments","hoisin":"high-sodium-condiments","teriyaki":"high-sodium-condiments","miso":"high-sodium-condiments","bouillon":"bouillon-broth","stock cube":"bouillon-broth","gravy":"bouillon-broth","consomme":"bouillon-broth","msg":"high-sodium-condiments","monosodium glutamate":"high-sodium-condiments","baking soda":"high-sodium-condiments","baking powder":"high-sodium-condiments","pickles":"pickled-foods","pickled":"pickled-foods","olives":"pickled-foods","capers":"pickled-foods","sauerkraut":"pickled-foods","kimchi":"pickled-foods","bacon":"cured-meat","ham":"cured-meat","prosciutto":"cured-meat","salami":"cured-meat","pepperoni":"cured-meat","chorizo":"cured-meat","sausage":"processed-meat","deli meat":"processed-meat","hot dog":"processed-meat","anchovies":"cured-meat","smoked salmon":"cured-meat","crisps":"salty-snacks","chips":"salty-snacks","pretzels":"salty-snacks","salted crackers":"salty-snacks","salted popcorn":"salty-snacks","salted nuts":"salty-snacks","instant noodles":"canned-high-sodium","ramen":"canned-high-sodium","canned soup":"canned-high-sodium","frozen dinner":"canned-high-sodium","ready meal":"canned-high-sodium","fast food":"fried-food","deep fried":"fried-food","battered":"fried-food","parmesan":"high-sodium-cheese","feta":"high-sodium-cheese","halloumi":"high-sodium-cheese","blue cheese":"high-sodium-cheese","processed cheese":"high-sodium-cheese","butter":"saturated-fat-heavy","cream":"saturated-fat-heavy","coconut oil":"saturated-fat-heavy","lard":"saturated-fat-heavy","margarine":"trans-fat","shortening":"trans-fat","pastry":"trans-fat","croissant":"trans-fat","soft drink":"sugary-drinks","soda":"sugary-drinks","cola":"sugary-drinks","energy drink":"sugary-drinks","sweetened juice":"sugary-drinks","lemonade":"sugary-drinks","beer":"alcohol","wine":"alcohol","spirits":"alcohol","olive oil":"olive-oil","avocado":"avocado","salmon":"oily-fish","sardines":"oily-fish","mackerel":"oily-fish","lentils":"legumes","chickpeas":"legumes","black beans":"legumes","brown rice":"brown-rice","quinoa":"quinoa","oats":"oats","barley":"barley","unsalted almonds":"unsalted-nuts","unsalted walnuts":"unsalted-nuts"}', '{"sodium_mg_meal_max":500,"sodium_mg_day_max":1500,"sodium_mg_day_ceiling":2300,"saturated_fat_pct_max":6,"fiber_g_day_min":25,"fiber_g_meal_min":8,"potassium_mg_meal_min":600}',
    '["dash","mediterranean","mind","flexitarian","volumetrics","high-protein","plant-based","vegan","vegetarian","pescatarian","diabetes-friendly","bone-health","gluten-free"]', '{"keto":"Focus on fish, eggs, vegetables and olive oil; keep keto partners salt additions off the shared dish. Keto processed meats are excluded.","paleo":"Lean meat, fish, vegetables, nuts and olive oil work well; avoid paleo-friendly cured meats and added salt","low-fodmap":"Use low-FODMAP vegetables; keep sodium low; rinse canned legumes","intermittent-fasting":"Timing pattern is orthogonal — follow sodium rules inside the eating window","whole30":"Whole30 is naturally low in processed food; avoid added salt and cured meats","macrobiotic":"Use low-sodium soy alternatives sparingly; avoid pickled and salted traditional foods","pritikin":"Highly compatible — both low-fat, low-sodium patterns","mcdougall":"Plant-based and low-sodium; avoid salty condiments","hclf-811":"Fruit and vegetables are naturally low in sodium; avoid salted nuts and condiments"}', '{"carnivore":"Processed and cured meats dominate; shared meals are difficult — use fresh unseasoned meat and separate condiments"}', 1
  );
INSERT INTO diet_catalog (
    diet_key, display_label, category, emoji, short_desc,
    evidence_grade, restrictiveness, is_timing_pattern, is_default,
    ai_rules, allowed_groups, restricted_groups, classifier_terms, macro_targets,
    easy_matches, adaptable_matches, hard_conflicts, is_condition
  ) VALUES (
    'diabetes-friendly', 'Diabetes-Friendly', 'condition', '🩸', 'Blood-sugar friendly eating — low-GI carbs, high fibre, no added sugar',
    'A', 3, 0, 0,
    'DIABETES-FRIENDLY DIET RULES — Follow strictly:

1. CARBOHYDRATE CONTROL:
   - Keep each main meal to roughly 30-60g of carbohydrate. This is a moderate default, not a prescription.
   - Choose low-glycaemic, high-fibre carbohydrates: legumes, barley, oats, quinoa, brown rice, whole-grain bread, whole-wheat pasta, sweet potato.
   - Do NOT use white rice, white bread, white pasta, instant noodles or refined flour.
   - Keep carbohydrate portions consistent across meals.
2. NO ADDED SUGAR AND NO SUGARY DRINKS:
   - No sugar, honey, maple syrup, agave, corn syrup or molasses.
   - No soft drinks, sweetened juice, energy drinks, sweet tea, lemonade or fruit punch.
   - No cake, cookies, biscuits, pastries, ice cream, candy or chocolate bars.
   - No jam, jelly, marmalade, ketchup, BBQ sauce, sweet chilli sauce, honey mustard or teriyaki.
   - No flavoured or fruit yogurt, condensed milk or sweetened dairy.
3. FRUIT: Use whole fruit, not juice. Prefer berries, apples, pears, oranges, kiwi and peaches. Keep portions moderate (1-2 portions per meal).
4. FIBRE: Include at least 8g fibre per main meal; aim for 25-30g per day. Build meals around non-starchy vegetables, legumes, nuts and seeds.
5. PROTEIN: Include at least 25g protein per main meal from fish, poultry, eggs, tofu, tempeh, legumes or plain yogurt. This blunts post-meal glucose spikes.
6. PLATE METHOD: Half the plate non-starchy vegetables, one quarter protein, one quarter low-GI carbohydrate.
7. FAT QUALITY: Use olive oil, avocado, nuts and oily fish. Limit butter, cream, fatty meat and fried food.
8. DRINKS: Water, sparkling water, unsweetened tea or black coffee only.
9. ALCOHOL: If included, keep it minimal and never on an empty stomach; it can cause delayed hypoglycaemia in people on insulin or sulfonylureas.
10. This app provides general dietary guidance, not medical advice. Do NOT calculate insulin doses or tell the user to change medication. People with type 1 diabetes, gestational diabetes, kidney disease or hypoglycaemia risk need individualised medical guidance.', '["non-starchy-vegetables","leafy-greens","whole-fruit","legumes","lentils","chickpeas","beans","whole-grains","brown-rice","quinoa","barley","oats","whole-grain-bread","whole-wheat-pasta","sweet-potatoes","fish","oily-fish","poultry","eggs","tofu","tempeh","plain-yogurt","nuts","seeds","olive-oil","avocado","herbs-spices","vinegar","unsweetened-tea-coffee"]', '["added-sugar","sugary-drinks","fruit-juice","refined-grains","sweets-desserts","sweetened-dairy","high-sugar-condiments","processed-snacks","fried-food"]', '{"sugar":"added-sugar","brown sugar":"added-sugar","white sugar":"added-sugar","caster sugar":"added-sugar","powdered sugar":"added-sugar","icing sugar":"added-sugar","honey":"added-sugar","maple syrup":"added-sugar","agave":"added-sugar","agave syrup":"added-sugar","corn syrup":"added-sugar","high fructose corn syrup":"added-sugar","molasses":"added-sugar","dextrose":"added-sugar","maltose":"added-sugar","sucrose":"added-sugar","syrup":"added-sugar","soft drink":"sugary-drinks","soda":"sugary-drinks","cola":"sugary-drinks","energy drink":"sugary-drinks","sports drink":"sugary-drinks","lemonade":"sugary-drinks","sweet tea":"sugary-drinks","fruit punch":"sugary-drinks","cordial":"sugary-drinks","juice":"fruit-juice","orange juice":"fruit-juice","apple juice":"fruit-juice","grape juice":"fruit-juice","white rice":"refined-grains","white bread":"refined-grains","white pasta":"refined-grains","instant noodles":"refined-grains","ramen":"refined-grains","white flour":"refined-grains","all purpose flour":"refined-grains","cornflakes":"refined-grains","puffed rice":"refined-grains","couscous":"refined-grains","cake":"sweets-desserts","cookie":"sweets-desserts","biscuit":"sweets-desserts","brownie":"sweets-desserts","muffin":"sweets-desserts","donut":"sweets-desserts","doughnut":"sweets-desserts","pastry":"sweets-desserts","croissant":"sweets-desserts","pie":"sweets-desserts","tart":"sweets-desserts","ice cream":"sweets-desserts","gelato":"sweets-desserts","sorbet":"sweets-desserts","pudding":"sweets-desserts","candy":"sweets-desserts","sweets":"sweets-desserts","chocolate bar":"sweets-desserts","milk chocolate":"sweets-desserts","white chocolate":"sweets-desserts","chocolate spread":"sweets-desserts","jam":"sweets-desserts","jelly":"sweets-desserts","marmalade":"sweets-desserts","preserves":"sweets-desserts","flavoured yogurt":"sweetened-dairy","flavored yogurt":"sweetened-dairy","fruit yogurt":"sweetened-dairy","vanilla yogurt":"sweetened-dairy","condensed milk":"sweetened-dairy","sweetened condensed milk":"sweetened-dairy","ketchup":"high-sugar-condiments","tomato ketchup":"high-sugar-condiments","bbq sauce":"high-sugar-condiments","barbecue sauce":"high-sugar-condiments","sweet chilli sauce":"high-sugar-condiments","sweet chili sauce":"high-sugar-condiments","honey mustard":"high-sugar-condiments","teriyaki":"high-sugar-condiments","plum sauce":"high-sugar-condiments","sweet and sour":"high-sugar-condiments","granola":"processed-snacks","cereal bar":"processed-snacks","granola bar":"processed-snacks","protein bar":"processed-snacks","potato chips":"processed-snacks","tortilla chips":"processed-snacks","chips":"fried-food","french fries":"fried-food","deep fried":"fried-food","battered":"fried-food","breaded":"fried-food","brown rice":"brown-rice","quinoa":"quinoa","barley":"barley","oats":"oats","lentils":"legumes","chickpeas":"legumes","black beans":"legumes","kidney beans":"legumes","salmon":"oily-fish","sardines":"oily-fish","mackerel":"oily-fish","plain yogurt":"plain-yogurt","greek yogurt":"plain-yogurt","olive oil":"olive-oil","avocado":"avocado","almonds":"nuts","walnuts":"nuts","chia seeds":"seeds","flaxseed":"seeds"}', '{"carbs_g_meal_min":30,"carbs_g_meal_max":60,"added_sugar_g_meal_max":3,"fiber_g_meal_min":8,"fiber_g_day_min":25,"protein_g_meal_min":25}',
    '["mediterranean","dash","mind","flexitarian","volumetrics","high-protein","plant-based","vegan","vegetarian","pescatarian","low-sodium","bone-health","gluten-free"]', '{"keto":"Keto is more restrictive on carbohydrate; follow ketos ceiling and keep the diabetic partners protein and non-starchy vegetables high. Monitor for hypoglycaemia risk if on medication.","paleo":"Paleo already excludes refined grains and sugar; add legumes or whole grains only for the non-paleo partner","low-fodmap":"Use low-FODMAP vegetables and grains; watch fruit portions and polyols","intermittent-fasting":"Timing pattern is orthogonal, but fasting plus diabetes medication carries hypoglycaemia risk — medical guidance required","whole30":"Whole30 is naturally sugar-free and refined-grain-free; compatible","macrobiotic":"Use brown rice and whole grains in measured portions; avoid sweetened condiments","pritikin":"Very compatible — both emphasise fibre-rich whole foods and low fat","mcdougall":"Starch-based; keep portions of rice/potatoes within the carbohydrate ceiling","hclf-811":"Fruit-heavy and high-carbohydrate — generally incompatible with the diabetes carbohydrate ceiling","carnivore":"No carbohydrate, but high saturated fat and no fibre — shared meals are difficult"}', '{"hclf-811":"Very high fruit and carbohydrate intake conflicts with the per-meal carbohydrate ceiling"}', 1
  );
INSERT INTO diet_catalog (
    diet_key, display_label, category, emoji, short_desc,
    evidence_grade, restrictiveness, is_timing_pattern, is_default,
    ai_rules, allowed_groups, restricted_groups, classifier_terms, macro_targets,
    easy_matches, adaptable_matches, hard_conflicts, is_condition
  ) VALUES (
    'bone-health', 'Bone Health', 'condition', '🦴', 'Osteoporosis-friendly eating — calcium, vitamin D, protein and vitamin K',
    'B', 2, 0, 0,
    'BONE HEALTH DIET RULES — Follow strictly:

1. CALCIUM AT EVERY MEAL:
   - Include a calcium-rich food in each main meal: plain yogurt, milk, fortified plant milk, calcium-set tofu, sardines or canned salmon with bones, kale, collards, bok choy, almonds, tahini or sesame.
   - Aim for roughly 300mg calcium per main meal, supporting 1,000-1,200mg per day.
   - Split calcium across meals; absorption is best in doses of 500mg or less.
2. VITAMIN D:
   - Include oily fish (salmon, sardines, mackerel), eggs and fortified foods. Sunlight is the main source.
   - Do not suggest high-dose vitamin D supplements; target 800-1,000 IU/day for adults 50+.
3. PROTEIN:
   - Include 25-35g protein per main meal from fish, poultry, eggs, dairy, tofu or legumes.
   - Protein supports bone matrix and muscle mass.
4. VITAMIN K AND MAGNESIUM:
   - Include leafy greens (kale, collards, bok choy, broccoli), nuts, seeds, legumes and whole grains.
5. LIMIT SODIUM:
   - No added salt; avoid soy sauce, bouillon, pickles, olives, cured and processed meat.
   - Keep meals to roughly 600mg sodium or less.
6. AVOID:
   - Liver, cod liver oil and high-dose retinol supplements (preformed vitamin A increases fracture risk).
   - Cola and phosphoric-acid soft drinks.
   - Energy drinks and excess caffeine (keep under 400mg/day).
   - Excess alcohol.
7. OXALATES: Spinach, rhubarb, beet greens and Swiss chard are high in oxalates and are poor calcium sources. Prefer kale, collards and bok choy for calcium.
8. PRUNES: 50g/day of prunes has evidence for bone density preservation; include them as a snack where appropriate.
9. This app provides general dietary guidance, not medical advice. Osteoporosis treatment, fracture prevention and supplement doses require a clinician.', '["dairy","plain-yogurt","milk","fortified-plant-milk","calcium-set-tofu","sardines-with-bones","canned-salmon-with-bones","oily-fish","fish","poultry","eggs","legumes","lentils","chickpeas","beans","low-oxalate-greens","kale","collard-greens","bok-choy","broccoli","vegetables","fruit","prunes","figs","whole-grains","oats","brown-rice","quinoa","barley","almonds","sesame","tahini","chia-seeds","flaxseed","olive-oil","herbs-spices"]', '["salt","high-sodium-condiments","soy-sauce","bouillon-broth","pickled-foods","cured-meat","processed-meat","liver","cod-liver-oil","high-retinol-supplements","cola-drinks","energy-drinks","alcohol","excess-caffeine"]', '{"salt":"salt","sea salt":"salt","soy sauce":"soy-sauce","tamari":"soy-sauce","bouillon":"bouillon-broth","stock cube":"bouillon-broth","gravy":"bouillon-broth","pickles":"pickled-foods","olives":"pickled-foods","capers":"pickled-foods","sauerkraut":"pickled-foods","bacon":"cured-meat","ham":"cured-meat","prosciutto":"cured-meat","salami":"cured-meat","sausage":"processed-meat","deli meat":"processed-meat","hot dog":"processed-meat","liver":"liver","beef liver":"liver","chicken liver":"liver","cod liver oil":"cod-liver-oil","retinol":"high-retinol-supplements","cola":"cola-drinks","soft drink":"cola-drinks","energy drink":"energy-drinks","espresso":"excess-caffeine","beer":"alcohol","wine":"alcohol","spirits":"alcohol","yogurt":"plain-yogurt","greek yogurt":"plain-yogurt","milk":"milk","fortified plant milk":"fortified-plant-milk","calcium set tofu":"calcium-set-tofu","tofu":"calcium-set-tofu","sardines":"sardines-with-bones","canned salmon":"canned-salmon-with-bones","salmon":"oily-fish","mackerel":"oily-fish","kale":"kale","collard greens":"collard-greens","bok choy":"bok-choy","broccoli":"broccoli","almonds":"almonds","sesame":"sesame","tahini":"tahini","chia seed